#include "ksGlobalTableTask.h"
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Global table semantic property failed");}
int main(){using T=ks::GlobalTableTask;uint64_t cases=0;auto verify=[&](unsigned selector,unsigned pattern){T t;unsigned words=0,selectors=0,clocks=0,guard=0;auto row=selector>5?5:selector;auto read=[&](bool select)->uint32_t{if(select){++selectors;return selector;}check(t.rowOffset()==row*20&&t.index()==words);return uint16_t(pattern+row*7919+t.index()*977);};auto write=[&](uint16_t value){check(t.index()==words&&value==uint16_t(pattern+row*7919+words*977));++words;};while(t.stage()!=T::Stage::Complete){check(++guard<64);auto cost=t.nextClocks(),s=unsigned(t.stage());check(t.advanceBefore(cost-1,read,write)==0&&unsigned(t.stage())==s);check(t.advanceBefore(cost,read,write)==cost);clocks+=cost;}check(selectors==1&&words==10&&clocks==296+unsigned(selector>5)*3);++cases;};for(unsigned selector=0;selector<256;++selector)for(unsigned pattern=0;pattern<256;++pattern)verify(selector,pattern);for(unsigned pattern=0;pattern<65536;++pattern)verify(pattern&255,pattern);std::cout<<"PASS: "<<cases<<" pure table properties; all selectors/byte patterns and full16-bit value patterns, clamped row binding, 10word order, exact296/299clocks, budget refusal\n";}
